from pathlib import Path

root = Path(__file__).resolve().parents[1]
app = root / 'src' / 'App.tsx'
css = root / 'src' / 'App.css'
text = app.read_text()

# Add homepage data helpers once.
marker = 'const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");\n'
insert = '''const storefrontCategoryCards = [\n  { name: "Glass", icon: "▧", description: "Toughened, decorative, partition and custom glass", action: "products" as Page },\n  { name: "Hardware", icon: "⚙", description: "Hinges, bolts, handles, stays and channels", action: "hardware" as Page },\n  { name: "Mirrors", icon: "◈", description: "Mirror solutions for homes and commercial spaces", action: "products" as Page },\n  { name: "Partitions", icon: "▥", description: "Glass partitions and office solutions", action: "products" as Page },\n  { name: "Door & Fittings", icon: "▤", description: "Complete glass door hardware essentials", action: "hardware" as Page },\n  { name: "Custom Solutions", icon: "✦", description: "Tell us your requirement and get a quote", action: "services" as Page },\n];\n\nconst productCategoryDescriptions: Record<string, string> = {\n  "Decorative Glass": "Decorative and designer glass for interiors.",\n  "Partition Glass": "Clean, modern glass for office and commercial partitions.",\n  "Designer Glass": "Premium designer glass for statement interiors.",\n  "Custom Glass": "Made-to-measure glass solutions for your project.",\n};\n'''
if 'const storefrontCategoryCards' not in text:
    text = text.replace(marker, marker + '\n' + insert)

# Replace the old services branch with a simple quick-commerce quote CTA if present.
start = text.find('page === "services" ? (')
end = text.find(': page === "contact" ?', start)
if start != -1 and end != -1:
    services = '''page === "services" ? (\n        <div className="storefront-quote-page">\n          <div className="storefront-quote-intro">\n            <p className="eyebrow">CUSTOM PROJECTS</p>\n            <h1>Need something specific?</h1>\n            <p>Send your requirement and our team will help you source the right glass, hardware or fitting.</p>\n          </div>\n          <div className="storefront-quote-card">\n            <div>\n              <span className="storefront-quote-badge">PROJECT SUPPORT</span>\n              <h2>Request a quote</h2>\n              <p>Perfect for sizes, designs, installation work, bulk orders and products you do not see in the catalogue.</p>\n            </div>\n            <form className="storefront-quote-form" onSubmit={async (e) => {\n              e.preventDefault();\n              if (!enquiry.name || !enquiry.phone || !enquiry.email || !enquiry.service || !enquiry.requirements) { setEnquiryMessage("Please fill in all fields."); return; }\n              setEnquiryLoading(true); setEnquiryMessage("");\n              const { error } = await supabase.from("enquiries").insert({ name: enquiry.name, phone: enquiry.phone, email: enquiry.email, service: enquiry.service, requirements: enquiry.requirements });\n              if (error) setEnquiryMessage(error.message); else { setEnquiryMessage("Enquiry submitted successfully. Our team will get back to you."); notify("Enquiry submitted successfully"); setEnquiry({ name: "", phone: "", email: "", service: "", requirements: "" }); }\n              setEnquiryLoading(false);\n            }}>\n              <label>Name<input value={enquiry.name} onChange={e => setEnquiry(v => ({ ...v, name: e.target.value }))} placeholder="Your name" /></label>\n              <label>Phone<input value={enquiry.phone} onChange={e => setEnquiry(v => ({ ...v, phone: e.target.value }))} placeholder="Phone number" /></label>\n              <label>Email<input type="email" value={enquiry.email} onChange={e => setEnquiry(v => ({ ...v, email: e.target.value }))} placeholder="Email address" /></label>\n              <label>Service required<select value={enquiry.service} onChange={e => setEnquiry(v => ({ ...v, service: e.target.value }))}><option value="">Select a service</option>{SERVICES.map(service => <option key={service} value={service}>{service}</option>)}</select></label>\n              <label className="storefront-quote-wide">Requirements<textarea value={enquiry.requirements} onChange={e => setEnquiry(v => ({ ...v, requirements: e.target.value }))} placeholder="Tell us what you need" /></label>\n              <button className="primary-btn storefront-quote-submit" type="submit" disabled={enquiryLoading}>{enquiryLoading ? "Submitting..." : "Submit Enquiry"}</button>\n              {enquiryMessage && <div className={enquiryMessage.toLowerCase().includes("success") ? "form-success storefront-quote-message" : "form-error storefront-quote-message"}>{enquiryMessage}</div>}\n            </form>\n          </div>\n        </div>\n      )\n      '''
    text = text[:start] + services + text[end:]

# Locate the home return branch and replace its hero/category/featured content with a store homepage.
home_start = text.find('page === "home" ? (')
next_branch = text.find(': page === "hardware" ?', home_start)
if home_start != -1 and next_branch != -1:
    home = '''page === "home" ? (\n        <>\n          <section className="storefront-hero">\n            <div className="storefront-hero-copy">\n              <p className="storefront-kicker">GLASS • HARDWARE • PROJECT SUPPLIES</p>\n              <h1>Everything you need for your glass project.</h1>\n              <p>Shop glass products and hardware with live stock, clear pricing and a simple cart-to-checkout experience.</p>\n              <div className="storefront-hero-actions">\n                <button className="primary-btn" onClick={() => navigate("products")}>Shop products</button>\n                <button className="secondary-btn" onClick={() => navigate("hardware")}>Shop hardware</button>\n              </div>\n            </div>\n            <div className="storefront-hero-image">\n              <img src={glassProduct} alt="Glass products" />\n              <div className="storefront-hero-tag"><strong>Ready to order?</strong><span>Choose your product, add to cart and checkout.</span></div>\n            </div>\n          </section>\n\n          <section className="storefront-benefits">\n            <div><strong>⚡ Fast support</strong><span>Quick help for product and project needs</span></div>\n            <div><strong>✓ Genuine products</strong><span>Managed catalogue and real inventory</span></div>\n            <div><strong>₹ Clear pricing</strong><span>Transparent pricing before checkout</span></div>\n            <div><strong>▣ Easy ordering</strong><span>Cart, checkout and order tracking</span></div>\n          </section>\n\n          <section className="section storefront-section">\n            <div className="section-heading"><p className="eyebrow">SHOP BY CATEGORY</p><h2>What are you looking for?</h2><p>Start with a category and find the right products for your job.</p></div>\n            <div className="storefront-category-grid">{storefrontCategoryCards.map(category => <button key={category.name} className="storefront-category-card" onClick={() => navigate(category.action)}><span className="storefront-category-icon">{category.icon}</span><div><h3>{category.name}</h3><p>{category.description}</p><strong>Shop now →</strong></div></button>)}</div>\n          </section>\n\n          <section className="section storefront-products-strip">\n            <div className="section-heading"><p className="eyebrow">POPULAR PRODUCTS</p><h2>Shop from the catalogue</h2><p>Products added or updated by your admin appear here automatically.</p></div>\n            {productsLoading ? <div className="loading">Loading products…</div> : <div className="products-grid storefront-product-grid">{filteredProducts.slice(0, 8).map(p => <article className="product-card" key={p.id}>\n              <div className="product-image">{p.image_url || p.image ? <img src={p.image_url || p.image} alt={p.name} /> : <span>No image</span>}</div>\n              <div className="product-info"><p className="product-category">{p.category}</p><h3>{p.name}</h3><p className="product-description">{productCategoryDescriptions[p.category] || p.description}</p><div className="product-pricing"><strong>{money(Number(p.offer_price ?? p.price ?? p.mrp ?? 0))}</strong>{p.mrp && Number(p.mrp) > Number(p.offer_price ?? p.price ?? p.mrp) && <del>{money(Number(p.mrp))}</del>}</div><p className={`product-stock ${p.stock <= 0 ? "out" : ""}`}>{p.stock > 0 ? `${p.stock} in stock` : "Out of stock"}</p><div className="card-actions"><button className="primary-btn" disabled={p.stock <= 0} onClick={() => addToCart(p)}>Add to cart</button><button className="secondary-btn" onClick={() => { setSelectedProduct(p); navigate("product"); }}>View</button></div></div>\n            </article>)}</div>}\n            <div className="storefront-centered-action"><button className="secondary-btn" onClick={() => navigate("products")}>View all products</button></div>\n          </section>\n\n          <section className="section storefront-service-banner">\n            <div><p className="eyebrow">PROJECT & SITE SUPPORT</p><h2>Need a custom size, installation or bulk requirement?</h2><p>Send your requirement directly to the team and manage enquiries from the admin dashboard.</p></div>\n            <button className="primary-btn" onClick={() => navigate("services")}>Request a quote</button>\n          </section>\n        </>\n      )\n      '''
    text = text[:home_start] + home + text[next_branch:]

app.write_text(text)

css_add = r'''\n/* Buildenza-style Glassmart storefront */\n.storefront-hero{display:grid;grid-template-columns:1.05fr .95fr;gap:50px;align-items:stretch;background:#fff;padding:55px 8% 45px}.storefront-hero-copy{display:flex;flex-direction:column;justify-content:center}.storefront-kicker{margin:0 0 14px;color:var(--red);font-size:12px;font-weight:900;letter-spacing:1.8px}.storefront-hero h1{font-size:54px;line-height:1.03;letter-spacing:-1.4px;color:var(--navy);max-width:700px;margin:0 0 18px}.storefront-hero-copy>p:not(.storefront-kicker){font-size:19px;line-height:1.65;color:#617287;max-width:650px;margin:0 0 27px}.storefront-hero-actions{display:flex;gap:12px;flex-wrap:wrap}.storefront-hero-image{min-height:420px;position:relative;border-radius:16px;overflow:hidden;background:#e9eff4}.storefront-hero-image img{width:100%;height:100%;object-fit:cover}.storefront-hero-tag{position:absolute;left:20px;right:20px;bottom:20px;padding:16px 18px;border-radius:10px;background:#102d4de8;color:#fff;display:flex;justify-content:space-between;gap:15px;align-items:center}.storefront-hero-tag strong{font-size:15px}.storefront-hero-tag span{font-size:13px;opacity:.85}.storefront-benefits{display:grid;grid-template-columns:repeat(4,1fr);background:#f7f9fb;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:22px 8%;gap:18px}.storefront-benefits>div{display:flex;flex-direction:column;gap:4px}.storefront-benefits strong{color:var(--navy);font-size:14px}.storefront-benefits span{color:#617287;font-size:13px;line-height:1.4}.storefront-section{background:#fff}.section-heading>p:last-child{color:#617287}.storefront-category-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.storefront-category-card{display:flex;align-items:flex-start;gap:18px;background:#fff;border:1px solid var(--line);border-radius:12px;padding:22px;text-align:left;min-height:165px;transition:.2s}.storefront-category-card:hover{border-color:#9eacb9;box-shadow:0 10px 25px #142d4610;transform:translateY(-2px)}.storefront-category-icon{width:58px;height:58px;flex:0 0 58px;border-radius:10px;background:#eef3f7;display:flex;align-items:center;justify-content:center;color:var(--navy);font-size:25px;font-weight:800}.storefront-category-card h3{color:var(--navy);margin:2px 0 7px;font-size:20px}.storefront-category-card p{color:#617287;margin:0 0 14px;line-height:1.45;font-size:14px}.storefront-category-card strong{color:var(--red);font-size:13px}.storefront-products-strip{background:#f7f9fb}.storefront-product-grid{grid-template-columns:repeat(4,1fr)}.storefront-centered-action{display:flex;justify-content:center;margin-top:28px}.storefront-service-banner{display:flex;justify-content:space-between;align-items:center;gap:25px;background:#fff;border-top:1px solid var(--line)}.storefront-service-banner h2{font-size:34px;color:var(--navy);margin:6px 0 10px;max-width:820px}.storefront-service-banner p:last-child{color:#617287;max-width:760px;line-height:1.6}.storefront-quote-page{width:100%;max-width:1450px;margin:auto;padding:50px 6% 80px}.storefront-quote-intro{margin-bottom:30px}.storefront-quote-intro h1{font-size:46px;color:var(--navy);margin:5px 0 12px}.storefront-quote-intro>p:last-child{font-size:18px;color:#617287}.storefront-quote-card{display:grid;grid-template-columns:.8fr 1.2fr;gap:50px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:42px}.storefront-quote-card h2{font-size:38px;color:var(--navy);margin:12px 0}.storefront-quote-card>div>p:last-child{font-size:16px;color:#617287;line-height:1.7}.storefront-quote-badge{font-size:12px;font-weight:900;letter-spacing:1.8px;color:var(--red)}.storefront-quote-form{display:grid;grid-template-columns:1fr 1fr;gap:18px}.storefront-quote-form label{display:block;font-weight:800;color:var(--navy);font-size:14px}.storefront-quote-form input,.storefront-quote-form select,.storefront-quote-form textarea{width:100%;margin-top:7px;padding:13px 14px;border:1px solid #cbd3dc;border-radius:6px;outline:none;background:#fff}.storefront-quote-form textarea{min-height:125px;resize:vertical}.storefront-quote-wide,.storefront-quote-submit,.storefront-quote-message{grid-column:1/-1}.storefront-quote-submit{justify-self:start}.storefront-quote-message{margin-top:-8px}\n@media(max-width:1000px){.storefront-hero{grid-template-columns:1fr}.storefront-hero-image{min-height:360px}.storefront-benefits{grid-template-columns:repeat(2,1fr)}.storefront-category-grid,.storefront-product-grid{grid-template-columns:repeat(2,1fr)}.storefront-quote-card{grid-template-columns:1fr}}\n@media(max-width:650px){.storefront-hero{padding:35px 18px}.storefront-hero h1{font-size:40px}.storefront-hero-image{min-height:290px}.storefront-hero-tag{display:block}.storefront-hero-tag span{display:block;margin-top:5px}.storefront-benefits{grid-template-columns:1fr;padding:18px}.storefront-category-grid,.storefront-product-grid{grid-template-columns:1fr}.storefront-service-banner{display:block}.storefront-service-banner .primary-btn{margin-top:15px;width:100%}.storefront-quote-page{padding:35px 18px 60px}.storefront-quote-card{padding:25px 20px}.storefront-quote-form{grid-template-columns:1fr}.storefront-quote-wide,.storefront-quote-submit,.storefront-quote-message{grid-column:auto}.storefront-quote-submit{width:100%}}\n'''
with css.open('a') as f:
    f.write('\n' + css_add)
